{'role': 'user', 'content': [{'tool_use_id': 'toolu_01PkVqhfuc3NU31jFPkvifUh', 'type': 'tool_result', 'content': '     1→import { useState, useCallback } from "react";
     2→
     3→interface WaveformView {
     4→  viewStart: number;
     5→  viewEnd: number;
     6→  setView: (start: number, end: number) => void;
     7→  resetView: () => void;
     8→  zoomToSection: (start: number, end: number, padding?: number) => void;
     9→}
    10→
    11→/**
    12→ * Manages zoom/scroll state for a waveform view.
    13→ * The WaveformCanvas component calls `setView` via its `onViewChange` callback.
    14→ */
    15→export function useWaveformView(duration: number): WaveformView {
    16→  const [viewStart, setViewStart] = useState(0);
    17→  const [viewEnd, setViewEnd] = useState(duration);
    18→
    19→  // Update when duration changes (new track loaded)
    20→  if (viewEnd > duration && duration > 0) {
    21→    setViewEnd(duration);
    22→    if (viewStart > duration) setViewStart(0);
    23→  }
    24→
    25→  const setView = useCallback(
    26→    (start: number, end: number) => {
    27→      setViewStart(Math.max(0, start));
    28→      setViewEnd(Math.min(duration, end));
    29→    },
    30→    [duration],
    31→  );
    32→
    33→  const resetView = useCallback(() => {
    34→    setViewStart(0);
    35→    setViewEnd(duration);
    36→  }, [duration]);
    37→
    38→  const zoomToSection = useCallback(
    39→    (start: number, end: number, padding = 0.1) => {
    40→      const sectionDuration = end - start;
    41→      const pad = sectionDuration * padding;
    42→      const newStart = Math.max(0, start - pad);
    43→      const newEnd = Math.min(duration, end + pad);
    44→      setViewStart(newStart);
    45→      setViewEnd(newEnd);
    46→    },
    47→    [duration],
    48→  );
    49→
    50→  return { viewStart, viewEnd, setView, resetView, zoomToSection };
    51→}
    52→'}]}

