     6→function resetStore() {
     7→  useBridgeStore.setState({
     8→    wsConnected: false,
     9→    status: "stopped",
    10→    port: 0,
    11→    networkInterface: null,
    12→    jarExists: false,
    13→    jreAvailable: false,
    14→    restartCount: 0,
    15→    routeCorrect: null,
    16→    routeWarning: null,
    17→    devices: {},
    18→    players: {},
    19→    isReceiving: false,
    20→    lastMessageAgeMs: -1,
    21→    dotStatus: "disconnected",
    22→    isStartingUp: true,
    23→  });
    24→}
    25→
    26→function makeBridgeState(overrides: Partial<BridgeState> = {}): BridgeState {
    27→  return {
    28→    status: "running",
    29→    port: 17400,
    30→    network_interface: "en0",
    31→    jar_path: "/path/to/jar",
    32→    jar_exists: true,
    33→    jre_available: true,
    34→    restart_count: 0,
    35→    route_correct: true,
    36→    route_warning: null,
    37→    devices: {},
    38→    players: {},
    39→    ...overrides,
    40→  };
    41→}
    42→
    43→describe("bridgeStore", () => {
    44→  beforeEach(resetStore);
    45→
    46→  describe("initial state", () => {
    47→    it("starts disconnected with no devices/players", () => {
    48→      const state = useBridgeStore.getState();
    49→      expect(state.wsConnected).toBe(false);
    50→      expect(state.status).toBe("stopped");
    51→      expect(state.dotStatus).toBe("disconnected");
    52→      expect(state.isStartingUp).toBe(true);
    53→      expect(state.isReceiving).toBe(false);
    54→      expect(Object.keys(state.devices)).toHaveLength(0);
    55→      expect(Object.keys(state.players)).toHaveLength(0);
    56→    });
    57→  });
    58→
    59→  describe("setWsConnected", () => {
    60→    it("updates wsConnected and recomputes isStartingUp", () => {
    61→      useBridgeStore.getState().setWsConnected(true);
    62→      const state = useBridgeStore.getState();
    63→      expect(state.wsConnected).toBe(true);
    64→      // status is still "stopped" so isStartingUp depends on that
    65→      // !wsConnected || status === "starting" → false || false → false
    66→      expect(state.isStartingUp).toBe(false);
    67→    });
    68→
    69→    it("WS connected + status starting = still starting up", () => {
    70→      // First set status to "starting"
    71→      useBridgeStore.getState().setBridgeState(makeBridgeState({ status: "starting" }));
    72→      useBridgeStore.getState().setWsConnected(true);
    73→      const state = useBridgeStore.getState();
    74→      expect(state.wsConnected).toBe(true);
    75→      expect(state.isStartingUp).toBe(true);
    76→    });
    77→
    78→    it("disconnecting sets isStartingUp back to true", () => {
    79→      useBridgeStore.getState().setWsConnected(true);
    80→      expect(useBridgeStore.getState().isStartingUp).toBe(false);
    81→
    82→      useBridgeStore.getState().setWsConnected(false);
    83→      expect(useBridgeStore.getState().isStartingUp).toBe(true);
    84→    });
    85→  });
    86→
    87→  describe("setBridgeState", () => {
    88→    it("updates all bridge fields from a BridgeState message", () => {
    89→      const devices = {
    90→        "169.254.20.101": {
    91→          device_name: "XDJ-AZ",
    92→          device_number: 1,
    93→          device_type: "cdj" as const,
    94→          uses_dlp: true,
    95→        },
    96→      };
    97→      const players = {
    98→        "1": {
    99→          bpm: 128,
   100→          pitch: 0,
   101→          playback_state: "playing",
   102→          is_on_air: true,
   103→          rekordbox_id: 42001,
   104→          beat_within_bar: 1,
   105→          track_type: "rekordbox",
   106→        },
   107→      };
   108→
   109→      useBridgeStore.getState().setBridgeState(
   110→        makeBridgeState({ devices, players, restart_count: 3 })
   111→      );
   112→
   113→      const state = useBridgeStore.getState();
   114→      expect(state.status).toBe("running");
   115→      expect(state.port).toBe(17400);
   116→      expect(state.networkInterface).toBe("en0");
   117→      expect(state.jarExists).toBe(true);
   118→      expect(state.jreAvailable).toBe(true);
   119→      expect(state.restartCount).toBe(3);
   120→      expect(state.routeCorrect).toBe(true);
   121→      expect(Object.keys(state.devices)).toHaveLength(1);
   122→      expect(state.devices["169.254.20.101"].device_name).toBe("XDJ-AZ");
